const body = $json.body || $json;
let sender = body?.whatsappInboundMessage?.from || body?.from || '';
let message = body?.whatsappInboundMessage?.text?.body || body?.text?.body;

if (!message && body?.whatsappInboundMessage?.interactive) {
  const interact = body.whatsappInboundMessage.interactive;
  message = interact.list_reply?.id || interact.button_reply?.id || interact.list_reply?.title || interact.button_reply?.title;
}

message = message || 'Hola';
let name = body?.whatsappInboundMessage?.customerProfile?.name || 'Cliente';

return {
  sender: String(sender).trim(),
  message: String(message).trim(),
  messageLower: String(message).trim().toLowerCase(),
  name: String(name).trim(),
  shop_slug: 'demo'
};

// =============================================================
// STATE MACHINE: Deterministic Booking Flow
// =============================================================

const msg = $('Extract Message').item.json.message;
const msgLower = $('Extract Message').item.json.messageLower;
const sender = $('Extract Message').item.json.sender;
const userName = $('Extract Message').item.json.name;

// Context from shop
const ctxRaw = $('Get Shop Context').item.json;
const ctx = Array.isArray(ctxRaw) ? ctxRaw[0] : ctxRaw;
const shopName = ctx?.shop_name || 'Peluquería';
const services = (ctx?.services || '').split(',').map(s => s.trim()).filter(Boolean);
const professionals = (ctx?.professionals || '').split(',').map(s => s.trim()).filter(Boolean);

// Session
const sessRaw = $('Get Session').item.json;
const sess = Array.isArray(sessRaw) ? sessRaw[0] : sessRaw;

let currentState = sess?.current_state || 'IDLE';
let intent = sess?.intent || null;
let service = sess?.service || null;
let professional = sess?.professional || null;
let preferredDate = sess?.preferred_date || null;
let preferredTime = sess?.preferred_time || null;

// =============================================================
// STEP 1: Detect Intent (if not already set)
// =============================================================
if (!intent || currentState === 'IDLE') {
  if (msgLower.includes('reservar') || msgLower.includes('turno') || msgLower.includes('agendar') || msgLower.includes('cita')) {
    intent = 'BOOK';
    currentState = 'AWAITING_SERVICE';
  } else if (msgLower.includes('cancelar')) {
    intent = 'CANCEL';
    currentState = 'AWAITING_CANCEL_SELECTION';
  } else if (msgLower.includes('horario') || msgLower.includes('servicio') || msgLower.includes('info')) {
    intent = 'INFO';
  } else {
    // Default to booking flow for greetings
    if (msgLower.includes('hola') || msgLower.includes('buenas')) {
      intent = 'GREET';
    } else {
      intent = 'UNKNOWN';
    }
  }
}

// =============================================================
// STEP 2: Parse user input based on current state
// =============================================================

// Try to extract service from message
if (!service && currentState === 'AWAITING_SERVICE') {
  for (const s of services) {
    const sLower = s.toLowerCase().split('(')[0].trim();
    if (sLower && msgLower.includes(sLower)) {
      service = s;
      currentState = 'AWAITING_PROFESSIONAL';
      break;
    }
  }
  // Also check if user selected from list (exact match)
  if (!service) {
    for (const s of services) {
      if (msg === s || msgLower === s.toLowerCase()) {
        service = s;
        currentState = 'AWAITING_PROFESSIONAL';
        break;
      }
    }
  }
}

// Try to extract professional from message
if (!professional && currentState === 'AWAITING_PROFESSIONAL') {
  for (const p of professionals) {
    const pLower = p.toLowerCase();
    const firstName = pLower.split(' ')[0];
    if ((pLower && msgLower.includes(pLower)) || (firstName && msgLower.includes(firstName))) {
      professional = p;
      currentState = 'AWAITING_DATE';
      break;
    }
  }
  // Exact match from list
  if (!professional) {
    for (const p of professionals) {
      if (msg === p || msgLower === p.toLowerCase()) {
        professional = p;
        currentState = 'AWAITING_DATE';
        break;
      }
    }
  }
}

// Try to extract date from message
if (!preferredDate && currentState === 'AWAITING_DATE') {
  const now = new Date();
  const pad = n => String(n).padStart(2, '0');
  const iso = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

  if (msgLower.includes('hoy')) {
    preferredDate = iso(now);
    currentState = 'AWAITING_TIME';
  } else if (msgLower.includes('mañana')) {
    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    preferredDate = iso(tomorrow);
    currentState = 'AWAITING_TIME';
  } else {
    // Try to match date patterns like "el 15", "para el 20", "10/02"
    const dayMatch = msgLower.match(/(?:el|para|dia)\s*(\d{1,2})/);
    if (dayMatch) {
      const d = new Date();
      d.setDate(Number(dayMatch[1]));
      if (d < now) d.setMonth(d.getMonth() + 1);
      preferredDate = iso(d);
      currentState = 'AWAITING_TIME';
    }
    // Match DD/MM or DD-MM
    const fullDateMatch = msgLower.match(/(\d{1,2})[\/-](\d{1,2})/);
    if (!preferredDate && fullDateMatch) {
      const d = new Date();
      d.setDate(Number(fullDateMatch[1]));
      d.setMonth(Number(fullDateMatch[2]) - 1);
      if (d < now) d.setFullYear(d.getFullYear() + 1);
      preferredDate = iso(d);
      currentState = 'AWAITING_TIME';
    }
  }
}

// Try to extract time from message (when selecting from list)
if (!preferredTime && currentState === 'AWAITING_TIME') {
  // Match HH:MM or H:MM
  const timeMatch = msg.match(/^(\d{1,2}):(\d{2})/);
  if (timeMatch) {
    preferredTime = `${timeMatch[1].padStart(2, '0')}:${timeMatch[2]}:00`;
    currentState = 'READY_TO_BOOK';
  }
}

// =============================================================
// STEP 3: Determine next action and response
// =============================================================

let action = 'REPLY';
let response = {};
let needsApiCall = null;
let updateSession = {};

if (intent === 'GREET') {
  response = {
    type: 'text',
    text: { body: `¡Hola! 👋 Bienvenido a *${shopName}*. ¿Querés reservar un turno?` }
  };
  updateSession = { current_state: 'IDLE', intent: null };

} else if (intent === 'BOOK') {

  if (!service) {
    // Ask for service
    const rows = services.slice(0, 10).map(s => ({ id: s, title: s.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💇 Nuestros Servicios' },
        body: { text: '¿Qué servicio te gustaría?' },
        footer: { text: shopName },
        action: {
          button: 'Ver Servicios',
          sections: [{ title: 'Servicios', rows: rows }]
        }
      }
    };
    updateSession = { current_state: 'AWAITING_SERVICE', intent: 'BOOK' };

  } else if (!professional) {
    // Ask for professional
    const rows = professionals.slice(0, 10).map(p => ({ id: p, title: p.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💈 Nuestros Profesionales' },
        body: { text: `Elegiste: *${service}*\n¿Con quién te gustaría atenderte?` },
        footer: { text: shopName },
        action: {
          button: 'Ver Profesionales',
          sections: [{ title: 'Profesionales', rows: rows }]
        }
      }
    };
    updateSession = { current_state: 'AWAITING_PROFESSIONAL', intent: 'BOOK', service: service };

  } else if (!preferredDate) {
    // Ask for date
    response = {
      type: 'text',
      text: { body: `Perfecto! *${service}* con *${professional}*.\n\n📅 ¿Para qué fecha querés el turno?\n\nPodés decir: "hoy", "mañana", o una fecha como "el 15" o "10/02"` }
    };
    updateSession = { current_state: 'AWAITING_DATE', intent: 'BOOK', service: service, professional: professional };

  } else if (!preferredTime) {
    // Need to fetch available times
    action = 'FETCH_TIMES';
    needsApiCall = 'checkAvailability';
    updateSession = { current_state: 'AWAITING_TIME', intent: 'BOOK', service: service, professional: professional, preferred_date: preferredDate };

  } else {
    // All data collected - book it!
    action = 'BOOK_APPOINTMENT';
    needsApiCall = 'bookAppointment';
    updateSession = { current_state: 'BOOKING', intent: 'BOOK', service: service, professional: professional, preferred_date: preferredDate, preferred_time: preferredTime };
  }

} else if (intent === 'CANCEL') {
  action = 'FETCH_APPOINTMENTS';
  needsApiCall = 'checkAppointments';
  updateSession = { current_state: 'AWAITING_CANCEL_SELECTION', intent: 'CANCEL' };

} else if (intent === 'INFO') {
  const serviceList = services.join(', ');
  const profList = professionals.join(', ');
  response = {
    type: 'text',
    text: { body: `ℹ️ *${shopName}*\n\n💇 *Servicios:* ${serviceList}\n💈 *Profesionales:* ${profList}\n\n¿Querés reservar un turno?` }
  };
  updateSession = { current_state: 'IDLE', intent: null };

} else {
  // Unknown - try to help
  response = {
    type: 'text',
    text: { body: `No entendí tu mensaje. Puedo ayudarte a:\n\n• *Reservar* un turno\n• *Cancelar* un turno\n• Ver *info* de servicios\n\n¿Qué querés hacer?` }
  };
  updateSession = { current_state: 'IDLE', intent: null };
}

return {
  action: action,
  response: response,
  needsApiCall: needsApiCall,
  updateSession: updateSession,
  context: {
    sender: sender,
    userName: userName,
    shopName: shopName,
    service: service,
    professional: professional,
    preferredDate: preferredDate,
    preferredTime: preferredTime
  }
};

const slots = $json;
const context = $('State Machine').item.json.context;
const shopName = context.shopName;
const preferredDate = context.preferredDate;

if (!slots || slots.length === 0) {
  return {
    response: {
      type: 'text',
      text: { body: `😕 No hay horarios disponibles para el ${preferredDate} con ${context.professional}.\n\n¿Querés probar otra fecha?` }
    },
    updateSession: { current_state: 'AWAITING_DATE' }
  };
}

const rows = slots.slice(0, 10).map(slot => {
  const time = slot.start_time ? slot.start_time.substring(11, 16) : slot;
  return { id: time, title: time, description: '' };
});

return {
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '🕐 Horarios Disponibles' },
      body: { text: `Fecha: *${preferredDate}*\nProfesional: *${context.professional}*\n\nElegí un horario:` },
      footer: { text: shopName },
      action: {
        button: 'Ver Horarios',
        sections: [{ title: 'Horarios', rows: rows }]
      }
    }
  },
  updateSession: { current_state: 'AWAITING_TIME' }
};

const result = $json;
const context = $('State Machine').item.json.context;

if (result.success) {
  const dateParts = context.preferredDate.split('-');
  const formattedDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
  const formattedTime = context.preferredTime.substring(0, 5);

  return {
    response: {
      type: 'text',
      text: { body: `✅ *¡Reserva Confirmada!*\n\n💇 *Servicio:* ${context.service}\n💈 *Profesional:* ${context.professional}\n📅 *Fecha:* ${formattedDate} a las ${formattedTime}\n\n📍 *Lugar:* ${context.shopName}\n\n¡Te esperamos! 🎉` }
    },
    updateSession: { current_state: 'IDLE', intent: null, service: null, professional: null, preferred_date: null, preferred_time: null }
  };
} else {
  return {
    response: {
      type: 'text',
      text: { body: `❌ No pudimos completar la reserva.\n\nError: ${result.error || 'Desconocido'}\n\n¿Querés intentar con otro horario?` }
    },
    updateSession: { current_state: 'AWAITING_TIME' }
  };
}

const appointments = $json;
const context = $('State Machine').item.json.context;

if (!appointments || appointments.length === 0) {
  return {
    response: {
      type: 'text',
      text: { body: `No tenés turnos pendientes. ¿Querés reservar uno nuevo?` }
    },
    updateSession: { current_state: 'IDLE', intent: null }
  };
}

const rows = appointments.slice(0, 10).map(apt => {
  const date = apt.start_time ? apt.start_time.substring(0, 10) : '';
  const time = apt.start_time ? apt.start_time.substring(11, 16) : '';
  const dateParts = date.split('-');
  const shortDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}` : date;

  return {
    id: apt.id,
    title: `${shortDate} ${time}`.slice(0, 24),
    description: `${apt.service_name || 'Servicio'} - ${apt.professional_name || ''}`
  };
});

return {
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '📋 Tus Turnos' },
      body: { text: 'Seleccioná el turno que querés cancelar:' },
      footer: { text: context.shopName },
      action: {
        button: 'Ver Turnos',
        sections: [{ title: 'Turnos Pendientes', rows: rows }]
      }
    }
  },
  updateSession: { current_state: 'AWAITING_CANCEL_SELECTION', intent: 'CANCEL' }
};
